#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_check_for_updates_setting_name() {
        let setting = SettingItem::CheckForUpdates;
        assert_eq!(setting.name(), "Automatic Update Checks");
    }

    #[test]
    fn test_apply_automatic_update_checks_enabled() {
        let mut config = Config::default();
        config.updates.check_enabled = false;

        let success = SettingsScreen::apply_setting_by_name(
            &mut config,
            "Automatic Update Checks",
            0,
        );

        assert!(success);
        assert!(config.updates.check_enabled);
    }

    #[test]
    fn test_apply_automatic_update_checks_disabled() {
        let mut config = Config::default();
        config.updates.check_enabled = true;

        let success = SettingsScreen::apply_setting_by_name(
            &mut config,
            "Automatic Update Checks",
            1,
        );

        assert!(success);
        assert!(!config.updates.check_enabled);
    }

    #[test]
    fn test_get_options_for_update_checks() {
        let config = Config::default();
        let screen = SettingsScreen::new();

        let options = screen.get_options(&config);
        let check_updates_setting = SettingItem::CheckForUpdates;
        let selected_idx = config.repo_mode;
        let all_settings = SettingItem::all(selected_idx);
        let setting_idx = all_settings
            .iter()
            .position(|s| *s == check_updates_setting)
            .unwrap();

        assert_eq!(options.len(), 2);
        assert_eq!(options[0].0, "Enabled");
        assert_eq!(options[1].0, "Disabled");
    }

    #[test]
    fn test_setting_item_all_contains_check_for_updates() {
        let settings = SettingItem::all(RepoMode::Standalone);
        let has_check_updates = settings.iter().any(|s| *s == SettingItem::CheckForUpdates);
        assert!(has_check_updates);
    }
}

